import { exportFile } from 'quasar';

export default {
  methods: {
    createAndExportCSV(
      tableRows: any,
      tableColumns: any,
      filename: string,
    ): any {
      //Stop process if no data
      if (!tableRows || !tableRows.length) return;
      //Extract keys for creating the header row
      const keys: string[] = tableColumns.map(
        (column: { name: string }) => column.name,
      );
      //Process data and join with comma for CSV
      const csvContent = [
        keys.map((key: string) => key.replace(/_/g, ' ')).join(','), // header row - replace underscore with space
        ...tableRows.map((row: { [x: string]: any }) =>
          keys
            .map((key) => `"${String(row[key] ?? '').replace(/"/g, '""')}"`)
            .join(','),
        ),
      ].join('\r\n');
      //Return the state - downloaded or failure
      return exportFile(filename, csvContent, 'text/csv');
    },
  },
};
